{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "The closest structural analogue, [11C]-JW642, shares the hexafluoroisopropyl [11C]carbamate motif and showed moderate, measurable brain uptake in mice by PET (SUV 0.2–0.8), directly demonstrating that this carbamate chemotype can access the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A pyrazole-containing CNS compound with good brain exposure in rats (total brain 2988 nM, unbound brain 63 nM, CSF 135 nM after oral dosing) supports the brain-penetrant potential of heteroaryl azetidine/pyrazole-like structures related to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A benzylpiperidine benzamide radiotracer showed good brain uptake in mice, supporting that benzylamine/aromatic amine-containing radioligands can cross the BBB despite moderate polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A structurally related ester radiotracer, 3-[18F]FEPB, showed low non-receptor-mediated brain uptake in rodents, providing a cautionary example that not all ester/carbamate radiotracers achieve adequate CNS exposure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a neutral, lipophilic [11C]carbamate PET tracer with favorable passive BBB properties. The highest-transfer analogue with the same hexafluoroisopropyl carbamate warhead showed moderate brain uptake in mice, and multiple related brain-penetrant compounds support CNS access. One structurally related ester tracer showed poor brain uptake, but its lower similarity and different linker chemistry reduce its weight. Overall, the evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "No direct quantitative brain/plasma or unbound brain concentration measurement exists for the exact query molecule.",
    "The closest analogue C05 reports SUV rather than a formal Kp or CSF/plasma ratio, limiting quantitative comparison.",
    "No explicit P-gp/efflux transporter data are available for the query or its closest analogue.",
    "Species differences between mouse, rat, and human BBB transport could affect translation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

